import { useEffect, useState } from 'react';
import axios from 'axios'


export default function Signin() {
    const [email, setEmail] = useState('')
    const [password, setPassword] = useState('')
    const handleSubmit = (e) => {
        e.preventDefault()
    }
    axios.post('http://localhost:5000/loginServer', {email, password})
        .then(res => {console.log(res.data)})
        .catch(err => {console.log(err)}) // Activate เมื่อเกิด Error
    
    useEffect(() => { 
        import('../css/signin.css')

        const form = document.querySelector("form")
        const eInput = form.querySelector(".input")
        const text = form.querySelector(".text")
            
        form.addEventListener("submit", (e)=>{
            e.preventDefault();
            let pattern = /^[^ ]+@[^ ]+\.[a-z]{2,3}$/;

            form.classList.add("error");
            form.classList.remove("valid");

            if (eInput.value == "") {
                text.innerText = "Email can't be blank";
            }
            else if (!eInput.value.match(pattern) ) {
                text.innerText = "Please enter a valid email";
            }
            else {
                form.classList.replace("error" , "valid");
                text.innerText = "";
            }
        });
    }, []);

    return (
        <>
        <form action="#">
            <div className="input-box">
                <input className="input" type="text" placeholder="Enter your email"/>
                <i className="ph ph-envelope email-icon"></i>
                <i className="ph-fill ph-warning-circle error-icon"></i>
                <i className="ph ph-check-circle passed-icon"></i>
                <input className="button" type="submit" value="Check"/>
            </div>
            <p className="text"></p>
            <div className="input-box">
                <input className="input" type="text" placeholder="Enter your email"/>
                <i className="ph ph-envelope email-icon"></i>
                <i className="ph-fill ph-warning-circle error-icon"></i>
                <i className="ph ph-check-circle passed-icon"></i>
                <input className="button" type="submit" value="Check"/>
            </div>
            <p className="text"></p>
        </form>
        </>
    )
}
